package com.trough.hot;
import android.os.*;import android.view.*;import java.io.File;import org.json.*;
/** Bounded representative live session; excludes AI/network and hardware input latency. */
final class HalfSwordSoakCheck implements Runnable {
 static final double PRACTICE_PELVIS_FLOOR_CM=80.; // Prototype standing gate on current zero-height training floor, not an original game rule.
 final boolean practice;int playerStarts,playerCompletions,playerSamples,swingPhase=-1;boolean swingPending,drillStarted;
 final HalfSwordView view;final HalfSwordAimCheck input;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();long started,heapStart,lastTick,maxTick;int stage,phase=-1,samples,startSteps;boolean pushing;double minPelvis=Double.POSITIVE_INFINITY,maxRadius,initialX,initialY,tailX,tailY,initialDrift=Double.NaN,tailDrift=Double.NaN;boolean initialAnchor,tailAnchor,idleTail;
 HalfSwordSoakCheck(HalfSwordView v){this(v,false);}HalfSwordSoakCheck(HalfSwordView v,boolean combinedPractice){view=v;practice=combinedPractice;input=new HalfSwordAimCheck(v);}void start(){ui.postDelayed(this,150);}void need(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}
 void body(int action,boolean left)throws Exception{HalfSwordBodyPushPad pad=view.bodyPushPad;long now=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(now,now,action,pad.getWidth()*(left?.13f:.87f),pad.getHeight()*.5f,0);try{need(pad.dispatchTouchEvent(e),"Movement input rejected");}finally{e.recycle();}}
 public void run(){try{long now=SystemClock.uptimeMillis();need(now-began<115000,"Live session timeout");need(view.isAttachedToWindow()&&view.renderVisible,"Live session scene unavailable");switch(stage){
 case 0:if(practice&&view.opponentFollow)input.click("Opponent spacing · prototype");if(view.characterRunning)input.click("Run / pause");input.click("Reset physics");input.click("Stance support setup");if(!view.weaponHoldEnabled)input.click("Compliant hold · prototype");stage=1;break;
 case 1:if(view.resetPending())break;input.click("Run / pause");started=lastTick=now;heapStart=Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory();startSteps=view.characterSteps;stage=2;break;
 case 2:need(view.characterRunning&&!view.characterFailed,"Live session interrupted");maxTick=Math.max(maxTick,now-lastTick);lastTick=now;if(view.characterSteps-startSteps<30)break;JSONObject o=input.observation();JSONArray pos=o.getJSONArray("pelvis_cm");minPelvis=Math.min(minPelvis,pos.getDouble(2));maxRadius=Math.max(maxRadius,Math.hypot(pos.getDouble(0),pos.getDouble(1)));if(practice)need(minPelvis>PRACTICE_PELVIS_FLOOR_CM,"Practice stance collapsed below prototype pelvis gate");need(maxRadius<400,"Character approached floor edge");need(view.weaponHeld&&!view.weaponReleased,"Grip lost");samples++;
  long elapsed=now-started;
  if(elapsed<15000){if(elapsed>=3000&&!initialAnchor){initialX=pos.getDouble(0);initialY=pos.getDouble(1);initialAnchor=true;}break;}
  if(Double.isNaN(initialDrift)){need(initialAnchor,"Initial idle anchor missing");initialDrift=Math.hypot(pos.getDouble(0)-initialX,pos.getDouble(1)-initialY);need(initialDrift<10,"Excess initial idle drift");}
  if(practice){
   need(view.passiveActive&&!view.opponentRelaxApplied,"Practice opponent unavailable");
   if(swingPending){boolean active;int frame;synchronized(view.signal){active=view.playerSwing.active;frame=view.playerSwing.frame;}if(active&&frame>0)playerSamples++;if(!active){need(frame>=90,"Practice player gesture cancelled before completion");playerCompletions++;swingPending=false;}}
   if(!drillStarted){input.click("Repeat opponent swings · practice");need(view.opponentDrillEnabled,"Practice drill enable failed");drillStarted=true;}
  }
  if(elapsed<75000){int next=(int)((elapsed-15000)/6000);if(next!=phase){if(pushing){body(MotionEvent.ACTION_CANCEL,false);pushing=false;}phase=next;input.aim(phase%2==0?25:-15,phase%2==0?25:-20);body(MotionEvent.ACTION_DOWN,phase%2!=0);pushing=true;}if(pushing&&(elapsed-15000)%6000>=1000){body(MotionEvent.ACTION_CANCEL,false);pushing=false;}if(practice&&swingPhase!=phase&&(elapsed-15000)%6000>=3000){input.click("Player swing");synchronized(view.signal){need(view.playerSwing.active,"Practice player swing rejected");}playerStarts++;swingPending=true;swingPhase=phase;}}
  else {if(!idleTail){if(practice)view.disableOpponentDrill();view.cancelAllTouchInputs();input.aim(0,0);idleTail=true;pushing=false;}if(elapsed>=78000&&!tailAnchor){tailX=pos.getDouble(0);tailY=pos.getDouble(1);tailAnchor=true;}}
  if(elapsed>=90000){need(tailAnchor,"Final idle anchor missing");tailDrift=Math.hypot(pos.getDouble(0)-tailX,pos.getDouble(1)-tailY);need(tailDrift<10,"Excess released idle drift");view.cancelAllTouchInputs();input.click("Run / pause");input.pausedSteps=-1;stage=3;}break;
 case 3:if(!input.pausedScene(true))break;if(practice){need(playerStarts>=5&&playerCompletions>=5&&playerSamples>=5,"Insufficient completed player gestures");need(view.opponentSwingStarts>=2&&!view.opponentDrillEnabled&&!view.opponentSwingActive,"Practice drill did not run/settle");}need(view.touchCapture.owners()==0&&!view.bodyPushActive,"Session retained input");finish(null);return;
 }ui.postDelayed(this,250);}catch(Throwable error){view.characterRunning=false;if(practice){view.disableOpponentDrill();synchronized(view.signal){view.playerSwing.cancel();}}view.cancelAllTouchInputs();view.refreshRunControl();finish(error.toString());}}
 void finish(String error){try{JSONObject d=new JSONObject();JSONObject perf=view.performance();boolean budget=stage==3&&samples>0&&maxTick<=350&&perf.optDouble("integrated_max_ms",Double.POSITIVE_INFINITY)<=16.7;d.put("minimum_practice_pelvis_cm",PRACTICE_PELVIS_FLOOR_CM).put("posture_gate_scope","Prototype standing acceptance on current zero-height training floor; not recovered original locomotion or knockdown rules").put("practice",practice).put("functional_passed",error==null).put("sample_budgets_passed",budget).put("ui_callback_budget_ms",350).put("integrated_step_budget_ms",16.7).put("player_starts",playerStarts).put("player_completions",playerCompletions).put("player_active_samples",playerSamples).put("opponent_swing_starts",view.opponentSwingStarts).put("passed",error==null&&(!practice||budget)).put("error",error==null?"":error).put("stage",stage).put("elapsed_ms",started==0?0:SystemClock.uptimeMillis()-started).put("initial_idle_drift_cm",Double.isFinite(initialDrift)?initialDrift:JSONObject.NULL).put("released_idle_drift_cm",Double.isFinite(tailDrift)?tailDrift:JSONObject.NULL).put("idle_window_seconds",12).put("samples",samples).put("physics_steps",view.characterSteps-startSteps).put("minimum_pelvis_cm",Double.isFinite(minPelvis)?minPelvis:JSONObject.NULL).put("max_radius_cm",maxRadius).put("maximum_ui_callback_gap_ms",maxTick).put("heap_start_bytes",heapStart).put("heap_end_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory()).put("performance",perf).put("module",HalfSwordBridge.loadedModuleSha256).put("time_ms",System.currentTimeMillis()).put("practice_scope",practice?"Explicit player gestures and deterministic opponent drill during movement/aim; no fighting AI, damage, hardware-input or full-game performance proof":"baseline only").put("scope","90-second visible session:15s initial idle,60s alternating body/aim/brake,15s released idle; each idle window measured after3s settling; excludes AI/network/hardware input latency; heap samples not forced-GC leak measurements");Payloads.writeSmall(new File(view.getContext().getFilesDir(),"home/.trough/"+(practice?"half-sword-practice-check-result.json":"half-sword-soak-check-result.json")),d.toString());}catch(Exception e){android.util.Log.e("Trough","Soak receipt",e);}}
}
